questionvariables.text:
stack_include_contrib("prooflib.mac");
/* All steps offered to the student: [key, text]. */
steps : [
  ["sub",     "Subtract \\(u\\) from both sides: \\(v - u = at\\)"],
  ["div",     "Divide both sides by \\(a\\): \\(\\dfrac{v - u}{a} = t\\)"],
  ["rew",     "Rewrite with \\(t\\) on the left: \\(t = \\dfrac{v - u}{a}\\)"],
  ["addu",    "Add \\(u\\) to both sides: \\(v + u = at\\)"],
  ["divpart", "Divide both sides by \\(a\\): \\(\\dfrac{v}{a} = u + t\\)"]
];
/* Shuffle the order in which the steps are offered. */
steps : random_permutation(steps);
/* Teacher's answer: the correct steps in order. */
ta : proof("sub", "div", "rew");
/* The correct keys, used to spot "right steps, wrong order". */
correct_keys : ["sub", "div", "rew"];

feedbackvariables.text:
/* The student's steps as a proof object, then as a list of keys. */
sa : parsons_decode(ans1);
sl : args(sa);
